dir$chcall.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$chcallHiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$chcallHiddenColumnByType(p);
      break;
	case 'ma_dv':
      p.reloadGrid(0, ['ma_dv', 'C', v]);
	break;
    default:
      break;
  }
}
&VoucherExRateValid02;
dir$chcall.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$chcallDisabledMasterField(p, p.grid(gindex));
  return true;
}
